-- =========================================
-- CUSTOMER SHOPPING BEHAVIOR ANALYSIS
-- Database: PostgreSQL
-- =========================================


--1. revenue analysis...
-- compared total revenue generated by male and famale customers.
select gender, sum(purchase_amount) as Total_revenue
	from customer_behavior
	group by gender;



--2. discount & spending analysis
--identified discount users whose purchase amounts were at or above the overall average

select customer_id, purchase_amount 
	from customer_behavior
	where discount_applied= 'Yes' 
	and purchase_amount>= (select avg(purchase_amount) from customer_behavior);



--3. product rating analysis.
-- ranked tthe top 5 products by average review rating.

select item_purchased,
	avg(review_rating) as "average product rating"
	from customer_behavior
	group by item_purchased
	order by avg(review_rating) desc
	limit 5;


--4. shipping analysis 
--compared average purchase amounts for standard and express shipping.

select shipping_type, round(avg(purchase_amount),2)
	from customer_behavior
	where shipping_type in ('standard', 'Express')
	group by shipping_type;



-- 5. subscription analysis
--compared customer counts, average spending, and total revenue between subscribers andn non subscribers

select subscription_status,
	count(customer_id) as total_customers,
	round(avg(purchase_amount),2) as avg_spend,
	round(sum(purchase_amount),2) as total_revenue
		from customer_behavior
			group by subscription_status
			order by total_revenue, avg_spend desc;


select * from customer_behavior;

-- 6. discount dependency analysis
-- identified the top 5 products by percentage of purchases with discounts applied.

select item_purchased,
	round(
			100.0*sum(
					case when discount_applied = 'Yes' then 1
					else 0 end)/count(*),2)
					as discount_rate
					from customer_behavior
					group by item_purchased
					order by discount_rate desc
					limit 5;



--7. Cusotmer segmentation
-- classified customers into new, returning, and loyal segments based on previous on previous purchased

with customer_type as (
    select
        customer_id,
        previous_purchases,
        case
            when previous_purchases = 1 then 'New'
            when previous_purchases between 2 and 10 then 'Returning'
            else 'Loyal'
        end as customer_segment
    from customer_behavior
)
select
    customer_segment,
    count(*) as number_of_customers
from customer_type
group by customer_segment
order by number_of_customers desc;


select * from customer_behavior;
				--8. product popularity analysis
-- compared subscription status among customers with more than 5 prvious purchase

with item_counts AS (
    select category, item_purchased,
        count (customer_id) AS total_orders,
        row_number() over (
            partition by category
            order by count(customer_id) DESC
        ) as rn
    from customer_behavior
    group by category, item_purchased
)
select *
from item_counts
where rn = 1;



	select * from customer_behavior;
	
				--9. reap buyer analysis
--compared subscription status among customers with more than 5 previous purchases.

select subscription_status, 
count (customer_id) as repeated_buyers
from customer_behavior
where previous_purchases>5
group by subscription_status;


				--10. age group analysis
-- compard total revenue across customer age groups.

select age_group, sum(purchase_amount) as total_revenue
from customer_behavior
group by age_group 
order by total_revenue desc;












	
